"use client";

/**
 * SegmentDisplay. A seven-segment readout, drawn the way a real one looks:
 * the segments a reading doesn't light stay faintly visible under the glass,
 * and the zeros that only pad it out print dim rather than vanishing, so
 * "88.5" on a four-digit face reads as a dim 0 and a lit 88.5.
 *
 * `screen` sits in its own dark well with its label engraved over it;
 * `flush` is the digits alone, for a screen you already have.
 *
 * For assistive technology it is the reading, said once, as it is: the
 * padding and the dark segments are drawing, not text.
 */
import type { CSSProperties } from "react";
import { useRoll } from "../roll";
import { CELL_H, COLON_DOTS, DP, LEAN, SEGMENTS, SEGMENT_POINTS, layout, place } from "./segments";
import "../scope/scope.css";
import "./segment-display.css";

export interface SegmentDisplayProps {
  /** The reading: digits, a minus, a dot, a colon, and the letters a segment face can draw. */
  value: string | number;
  /** What it reads: the accessible name, and engraved over a `screen` display. */
  label: string;
  /** Engraved after the digits: "MHz", "kg". */
  unit?: string;
  /** At least this many digit cells. A shorter reading is padded on the left. */
  digits?: number;
  /** What fills the padding: dim zeros (`"0"`, default), the way a counter shows them, or blanks (`" "`). */
  pad?: "0" | " ";
  /** Draw the segments a reading doesn't light, faintly, as a real display shows them. Default true. */
  ghost?: boolean;
  /** Lit in the accent (default); `false` lights it cream, for a value that isn't live. */
  glow?: boolean;
  /** A new reading rolls to its digits, each stepping through the ones in between. */
  roll?: boolean;
  /** Digit height: `sm` 24px, `md` 40px (default), `lg` 64px. */
  size?: "sm" | "md" | "lg";
  /** `screen` (default) sits in its own dark well; `flush` is the digits alone. */
  variant?: "screen" | "flush";
  /** `emissive` (default): a dark screen that glows. `reflective`: the paper-coloured glass of a pocket calculator, printed in ink. */
  screen?: "emissive" | "reflective";
}

export function SegmentDisplay({
  value,
  label,
  unit,
  digits = 0,
  pad = "0",
  ghost = true,
  glow = true,
  roll = false,
  size = "md",
  variant = "screen",
  screen = "emissive",
}: SegmentDisplayProps) {
  const text = String(value);
  const shown = useRoll(text, { enabled: roll });
  const cells = layout(shown, digits, pad);
  const { x, width } = place(cells);
  return (
    <div
      className="echo-segment-display"
      data-variant={variant}
      data-size={size}
      data-glow={glow ? "" : undefined}
      data-ghost={ghost ? "" : undefined}
      data-echo-screen={screen === "reflective" ? "reflective" : undefined}
      role="group"
      aria-label={label}
    >
      {variant === "screen" ? (
        <span className="echo-segment-display__label" aria-hidden="true">
          {label}
        </span>
      ) : null}
      <span className="echo-segment-display__row">
        <svg
          className="echo-segment-display__face"
          viewBox={`0 0 ${width} ${CELL_H}`}
          // The one dynamic value, as a variable the stylesheet reads: the
          // face's proportions, so its width follows the digit height.
          style={{ "--seg-ratio": (width / CELL_H).toFixed(4) } as CSSProperties}
          aria-hidden="true"
          focusable="false"
        >
          {cells.map((cell, i) =>
            cell.kind === "colon" ? (
              <g key={i} transform={`translate(${x[i]} 0) skewX(${-LEAN})`}>
                {COLON_DOTS.map((dot, j) => (
                  <circle key={j} cx={dot.cx} cy={dot.cy} r={dot.r} data-state="lit" />
                ))}
              </g>
            ) : (
              <g key={i} transform={`translate(${x[i]} 0) skewX(${-LEAN})`}>
                {SEGMENTS.map((s) => (
                  <polygon
                    key={s}
                    points={SEGMENT_POINTS[s]}
                    data-state={cell.lit.includes(s) ? (cell.pad ? "dim" : "lit") : "off"}
                  />
                ))}
                <circle cx={DP.cx} cy={DP.cy} r={DP.r} data-state={cell.dp ? "lit" : "off"} />
              </g>
            ),
          )}
        </svg>
        {unit ? (
          <span className="echo-segment-display__unit" aria-hidden="true">
            {unit}
          </span>
        ) : null}
      </span>
      <span className="echo-segment-display__said">{unit ? `${text} ${unit}` : text}</span>
    </div>
  );
}

/**
 * SegmentDisplay. Lit segments glow in the accent; the dark ones sit faintly
 * under the glass; padding zeros print dim. Composes var(--echo-*) — no hex
 * literals; the only fixed values are the single-key-light occlusion model.
 */
.echo-segment-display {
  --seg-h: 40px;
  display: inline-grid;
  justify-items: start;
  gap: var(--echo-space-3);
  max-width: 100%;
  min-width: 0;
}
.echo-segment-display[data-size="sm"] {
  --seg-h: 24px;
}
.echo-segment-display[data-size="lg"] {
  --seg-h: 64px;
}

/* screen: its own dark well, like LcdChip's. */
.echo-segment-display[data-variant="screen"] {
  padding: var(--echo-space-5) var(--echo-space-7) var(--echo-space-6);
  border-radius: var(--echo-radius-lg);
  background: linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%);
  box-shadow: var(
    --echo-shadow-well-screen,
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
}

.echo-segment-display__label,
.echo-segment-display__unit {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
  line-height: var(--echo-leading-tight, 1.25);
}

.echo-segment-display__row {
  display: inline-flex;
  align-items: flex-end;
  gap: var(--echo-space-3);
  max-width: 100%;
  min-width: 0;
}

/*
 * Sized by its width, from the digit height it wants: in a narrow column it
 * shrinks, digits and all, rather than pushing the column open.
 */
.echo-segment-display__face {
  display: block;
  flex: 0 1 auto;
  min-inline-size: 0;
  inline-size: calc(var(--seg-h) * var(--seg-ratio));
  max-inline-size: 100%;
  block-size: auto;
  aspect-ratio: var(--seg-ratio);
  overflow: visible;
}

/* Lit: the accent, emitting. Unlit displays light in cream. */
.echo-segment-display__face [data-state="lit"] {
  fill: var(--echo-text);
}
.echo-segment-display__face [data-state="dim"] {
  fill: color-mix(in oklab, var(--echo-text) 28%, transparent);
}
.echo-segment-display[data-glow] .echo-segment-display__face {
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--echo-lcd-glow) 45%, transparent));
}
.echo-segment-display[data-glow] .echo-segment-display__face [data-state="lit"] {
  fill: var(--echo-accent-ink, var(--echo-accent-glow));
}
.echo-segment-display[data-glow] .echo-segment-display__face [data-state="dim"] {
  fill: color-mix(in oklch, var(--echo-accent-glow) 30%, transparent);
}

/* The dark segments under the glass. */
.echo-segment-display__face [data-state="off"] {
  fill: transparent;
}
.echo-segment-display[data-ghost] .echo-segment-display__face [data-state="off"] {
  fill: color-mix(in oklab, var(--echo-text) 6%, transparent);
}

/* The reading, said once, as it is. */
.echo-segment-display__said {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (forced-colors: active) {
  .echo-segment-display[data-variant="screen"] {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-segment-display__face {
    filter: none;
  }
  .echo-segment-display .echo-segment-display__face [data-state="lit"] {
    fill: CanvasText;
  }
  .echo-segment-display .echo-segment-display__face [data-state="dim"] {
    fill: GrayText;
  }
  .echo-segment-display .echo-segment-display__face [data-state="off"] {
    fill: transparent;
  }
}

/**
 * The seven-segment face. Pure: no React, no DOM, so what lights for a given
 * reading can be tested on its own and shared by everything that draws
 * segments (SegmentDisplay, and the readouts inside Tuner and Keypad).
 *
 *    ─a─
 *   f   b
 *    ─g─
 *   e   c
 *    ─d─   .dp
 *
 * A real segment display never loses the segments it isn't using: they sit
 * dark under the glass, faintly visible. So a cell always draws all seven,
 * and a reading only decides which of them are lit.
 */

export type Segment = "a" | "b" | "c" | "d" | "e" | "f" | "g";
export const SEGMENTS: readonly Segment[] = ["a", "b", "c", "d", "e", "f", "g"];

/** Which segments each character lights. What a seven-segment face can draw, and nothing it can't. */
const FACE: Readonly<Record<string, string>> = {
  "0": "abcdef",
  "1": "bc",
  "2": "abdeg",
  "3": "abcdg",
  "4": "bcfg",
  "5": "acdfg",
  "6": "acdefg",
  "7": "abc",
  "8": "abcdefg",
  "9": "abcdfg",
  " ": "",
  "-": "g",
  _: "d",
  "°": "abfg",
  A: "abcefg",
  b: "cdefg",
  C: "adef",
  c: "deg",
  d: "bcdeg",
  E: "adefg",
  F: "aefg",
  G: "acdef",
  H: "bcefg",
  h: "cefg",
  I: "ef",
  J: "bcde",
  L: "def",
  n: "ceg",
  o: "cdeg",
  P: "abefg",
  r: "eg",
  S: "acdfg",
  t: "defg",
  U: "bcdef",
  u: "cde",
  y: "bcdfg",
};

/** The segments a character lights, or null when the face can't draw it. */
export function segmentsFor(ch: string): readonly Segment[] | null {
  const lit = FACE[ch] ?? FACE[ch.toUpperCase()] ?? FACE[ch.toLowerCase()];
  return lit === undefined ? null : (lit.split("") as Segment[]);
}

/** Whether every character of `text` can be drawn (a dot and a colon always can). */
export function canDraw(text: string): boolean {
  return [...text].every((ch) => ch === "." || ch === ":" || segmentsFor(ch) !== null);
}

/**
 * One position on the face.
 *
 * - `digit`: a seven-segment cell; `lit` is what shows, `dp` its decimal point.
 * - `colon`: the two dots between hours and minutes.
 *
 * `pad` marks a cell the reading didn't fill, added to reach `digits`: a
 * padding zero prints dim (a counter's leading zeros), a padding blank shows
 * only its dark segments.
 */
export type Cell =
  | { kind: "digit"; lit: readonly Segment[]; dp: boolean; pad: boolean }
  | { kind: "colon" };

/**
 * Lays a reading out on the face: right-aligned, the way a counter's digits
 * are, so a shorter reading gains cells on the left.
 *
 * A dot lights the decimal point of the cell before it (a dot with no cell
 * before it gets a blank one); a colon is its own narrow cell. A character
 * the face can't draw is a blank cell.
 */
export function layout(text: string, digits = 0, pad: "0" | " " = "0"): Cell[] {
  const cells: Cell[] = [];
  for (const ch of text) {
    if (ch === ".") {
      const last = cells.at(-1);
      if (last && last.kind === "digit" && !last.dp) cells[cells.length - 1] = { ...last, dp: true };
      else cells.push({ kind: "digit", lit: [], dp: true, pad: false });
      continue;
    }
    if (ch === ":") {
      cells.push({ kind: "colon" });
      continue;
    }
    cells.push({ kind: "digit", lit: segmentsFor(ch) ?? [], dp: false, pad: false });
  }
  const count = cells.filter((c) => c.kind === "digit").length;
  const fill: Cell[] = [];
  for (let i = count; i < digits; i++) {
    fill.push({ kind: "digit", lit: pad === "0" ? (segmentsFor("0") ?? []) : [], dp: false, pad: true });
  }
  // A minus leads its padding zeros (-05, never 0-5); blanks still lead the lot.
  if (pad === "0" && text.startsWith("-")) return [cells[0]!, ...fill, ...cells.slice(1)];
  return [...fill, ...cells];
}

/* ---- Geometry, in one cell's units: 60 wide, 100 tall -------------------- */

export const CELL_W = 60;
export const COLON_W = 22;
export const CELL_H = 100;

const L = 10;
const R = 46;
const T = 6;
const M = 50;
const B = 94;
/** How thick a segment is, and the gap where two meet. */
const TH = 9;
const GAP = 2.5;

function horizontal(y: number, x1: number, x2: number): string {
  const h = TH / 2;
  return `${x1},${y} ${x1 + h},${y - h} ${x2 - h},${y - h} ${x2},${y} ${x2 - h},${y + h} ${x1 + h},${y + h}`;
}
function vertical(x: number, y1: number, y2: number): string {
  const h = TH / 2;
  return `${x},${y1} ${x + h},${y1 + h} ${x + h},${y2 - h} ${x},${y2} ${x - h},${y2 - h} ${x - h},${y1 + h}`;
}

/** Each segment's polygon points in a cell. */
export const SEGMENT_POINTS: Readonly<Record<Segment, string>> = {
  a: horizontal(T, L + GAP, R - GAP),
  g: horizontal(M, L + GAP, R - GAP),
  d: horizontal(B, L + GAP, R - GAP),
  f: vertical(L, T + GAP, M - GAP),
  b: vertical(R, T + GAP, M - GAP),
  e: vertical(L, M + GAP, B - GAP),
  c: vertical(R, M + GAP, B - GAP),
};

/** The decimal point, bottom right of a cell. */
export const DP = { cx: R + 8, cy: B, r: 4.5 } as const;
/** The colon's two dots, centred in its cell. */
export const COLON_DOTS = [
  { cx: COLON_W / 2, cy: 32, r: 4.5 },
  { cx: COLON_W / 2, cy: 68, r: 4.5 },
] as const;

/** A segment face leans forward, as they do. The lean moves the bottom left. */
export const LEAN = 5;
/** How far the lean pushes a cell's bottom left, so the face can make room for it. */
export const LEAN_OFFSET = Math.ceil(Math.tan((LEAN * Math.PI) / 180) * CELL_H);

/** Where each cell starts, and the face's whole width. */
export function place(cells: readonly Cell[]): { x: number[]; width: number } {
  const x: number[] = [];
  let at = LEAN_OFFSET;
  for (const cell of cells) {
    x.push(at);
    at += cell.kind === "colon" ? COLON_W : CELL_W;
  }
  return { x, width: at };
}
